#!/usr/bin/env node
/**
 * Trims each `*_large.csv` fixture (1,000,000 rows, generated by
 * `scripts/fixtures/generate.ts --large`) down to the byte ceiling
 * `csv-stream.ts` actually enforces (`MAX_FILE_SIZE_BYTES` = 50 * 1024 *
 * 1024), keeping only whole CSV rows — never cutting a row in half.
 *
 * Per docs/decisions/08's "Which file size" section: for all three
 * canonical schemas the byte ceiling binds before the row ceiling, so this
 * — not the untrimmed 1,000,000-row file — is the largest file each
 * schema can actually pass the ceiling at, and is what
 * `bench/storage-benchmark.ts` benchmarks against.
 */
import { createReadStream, createWriteStream } from "node:fs"
import { createInterface } from "node:readline"
import path from "node:path"

const LIMIT_BYTES = 50 * 1024 * 1024
const SOURCE_DIR = path.join(process.cwd(), "tests/fixtures/generated")
const FIXTURES = ["transactions_stripe", "customers_saaS", "events_product"]

async function trim(fixture) {
  const sourcePath = path.join(SOURCE_DIR, `${fixture}_large.csv`)
  const outPath = path.join(SOURCE_DIR, `${fixture}_ceiling.csv`)

  const lines = createInterface({ input: createReadStream(sourcePath), crlfDelay: Infinity })
  const out = createWriteStream(outPath)

  let bytesWritten = 0
  let rowsWritten = 0
  let isHeader = true

  for await (const line of lines) {
    const bytes = Buffer.byteLength(line, "utf8") + 1 // +1 for the newline this loop re-adds
    if (!isHeader && bytesWritten + bytes > LIMIT_BYTES) {
      break
    }
    out.write(`${line}\n`)
    bytesWritten += bytes
    if (isHeader) {
      isHeader = false
    } else {
      rowsWritten += 1
    }
  }

  await new Promise((resolve, reject) => {
    out.end((error) => (error ? reject(error) : resolve()))
  })

  console.log(
    `${path.basename(outPath)}: ${rowsWritten} rows, ${bytesWritten} bytes (${(bytesWritten / 1024 / 1024).toFixed(2)} MiB)`,
  )
}

for (const fixture of FIXTURES) {
  // Sequential: these are large streaming reads/writes on the same disk — no benefit to
  // parallelizing, and sequential output is easier to read.
  // eslint-disable-next-line no-await-in-loop
  await trim(fixture)
}
